SettingsSearchHandlerAsyncWaiter::SettingsSearchHandlerAsyncWaiter(
    SettingsSearchHandler* proxy) : proxy_(proxy) {}

SettingsSearchHandlerAsyncWaiter::~SettingsSearchHandlerAsyncWaiter() = default;


void SettingsSearchHandlerAsyncWaiter::Search(
    const ::std::u16string& query, uint32_t max_results, std::vector<SearchResultPtr>* out_results) {
  base::RunLoop loop;
  proxy_->Search(
      std::move(query),
      std::move(max_results),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<SearchResultPtr>* out_results
,
             std::vector<SearchResultPtr> results) {*out_results = std::move(results);
            loop->Quit();
          },
          &loop,
          out_results));
  loop.Run();
}

std::vector<SearchResultPtr> SettingsSearchHandlerAsyncWaiter::Search(
    const ::std::u16string& query, uint32_t max_results) {
  std::vector<SearchResultPtr> async_wait_result;
  Search(std::move(query),std::move(max_results),&async_wait_result);
  return async_wait_result;
}






